import styles from "./index.module.scss";

export default function WorkCard({ title, desc, img }) {
  return (
    <div className={`${styles.card} mb-5 border bg-light rounded`}>
      <div className={`${styles.cardInfo} p-4`}>
        <h3 className="text-capitalize m-0 pe-3">{title}</h3>
        <p className="present-p">{desc}</p>
      </div>
      <picture className={`${styles.cardImg} d-flex flex-justify-end`}>
        <img className="img-fluid" src={img} alt={title} loading="lazy" />
      </picture>
    </div>
  );
}
